CHECKSUM = "b69fd5d71319baa35e2d5d81f2fa06adcd206ab938ec5f0e3d3aa37850ad99d1"


def install(target_dir=None):
    """번들을 해동하여 target_dir에 파일을 설치한다."""
    if target_dir is None:
        target_dir = os.path.dirname(os.path.abspath(__file__))
    print(f"[setup] 설치 경로: {target_dir}")
    raw = gzip.decompress(base64.b64decode(DATA.strip()))
    sha = hashlib.sha256(base64.b64decode(DATA.strip())).hexdigest()
    if sha != CHECKSUM:
        print(f"[ERROR] 체크섬 불일치!\n  기대: {CHECKSUM}\n  실제: {sha}")
        sys.exit(1)
    bundle = json.loads(raw)
    for fname, content in bundle.items():
        fpath = os.path.join(target_dir, fname)
        # 기존 파일 백업
        if os.path.exists(fpath):
            bak = fpath + ".bak"
            try:
                os.replace(fpath, bak)
                print(f"  [backup] {fname} -> {fname}.bak")
            except Exception as e:
                print(f"  [WARN] 백업 실패 {fname}: {e}")
        with open(fpath, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        print(f"  [OK] {fname} ({len(content):,} chars)")
    print(f"[setup] 설치 완료 ({len(bundle)}개 파일)")


if __name__ == "__main__":
    install()
